import hashlib,json,pathlib
H=pathlib.Path(__file__).resolve().parent;P='additional_pfp_infrastructure_remaining';f=json.loads((H/(P+'_preparation.json')).read_text())['files'];rp=H/(P+'.json');r=json.loads(rp.read_text())
def ev(i,a,b):return {'path':f[i]['path'],'sha256':f[i]['sha256'],'lines':[a,b]}
rows=[
('038','5NF sufficient-component shortcut contradicts its own counterexample','The sufficient_key_component_test claims that every JD component containing a candidate key makes the JD key-implied. The four-tuple binary parity relation satisfies every pair key but its three pair projections join to eight tuples. Correct contrary explanations exist elsewhere in this same file and SKNF, so the shortcut field is internally inconsistent.',[ev(398,34,58),ev(398,108,122),ev(406,38,69)],['048'],'Remove or qualify the sufficient shortcut in a future version; retain the counterexample and validate machine-consumed fields against the formal definition.'),
('039','Generator-only split-retraction check omits homomorphism premise','The contract requires r(u(x))=x on the base but calls generator evaluation sufficient without requiring u and r preserve the generating operations. A Z/3Z table fixes generator1 and fails at2. Set retraction also does not automatically preserve arbitrary relations.',[ev(431,41,44),ev(431,76,90)],['049'],'Require verified homomorphisms and a generated-carrier theorem or enumerate every finite base element; distinguish set retraction from relational preservation.'),
('040','Sign-switching substrate makes its closed obstruction impossible','The main GF(2) cycle criterion is sound. But d1 is defined as all cycle sums, whose kernel equals the cut-space im(d0); the declared ker(d1)/im(d0) is therefore trivial. An odd cycle has d1(s)!=0 and cannot be residual_closed in this complex. The triangle countermodel enumerates all eight sign cochains.',[ev(456,41,49),ev(456,119,130)],['050'],'Use Q1=C1/im(d0) for graph sign classes or the ordinary graph complex with no2-cells, and keep open/closed classification consistent with the actual chosen d1.'),
('041','Fermion average-sign lower bound fails for exact cancellation','For signed weights c=(1,-1), a repair image spanning c has quotient norm Phi=0 while average sign is0. The declared bound average_sign>=1-Phi/||c||1 demands1. A sign(Real(det)) rule also requires an admitted real nonzero determinant, absent from the generic anti-Hermitian declaration.',[ev(470,28,30),ev(470,47,66)],['051'],'Replace the false bound with a theorem using explicitly bound positive mass and survivor/cancellation data; refuse zero or complex determinant sign encodings outside the admitted domain.'),
('042','Stochasticity does not imply monotone return trace or uniformization','The transition matrix swapping two states is nonnegative and row-stochastic but P(t)=Tr(M^t)/2 alternates1,0,1,0. Thus monotonicity and asymptotic uniformization need additional spectral/aperiodicity hypotheses; row-sum checks alone also omit nonnegative entries.',[ev(474,23,29),ev(474,44,58)],['052'],'Specify lazy/reversible positive-semidefinite diffusion or a continuous-time semigroup and separately validate positivity, irreducibility/periodicity, derivative domain and empirical scaling.'),
('043','Trivial intersection does not protect the scalar component','The L1 contract claims im(D) intersect C0={0} prevents scalar absorption. D(a)=(a,a) has trivial intersection with the pure scalar axis but changes the scalar coordinate and exactly absorbs omega=(1,1). The correct stronger fixed-projection condition is projection_C0 D=0.',[ev(480,43,48),ev(480,60,69),ev(480,99,102)],['053'],'State the precise protected observable and enforce its composition with D is zero, or explicitly weaken the claim to excluding pure-scalar image vectors.'),
('044','WDW denominator upper bound can understate relative residual','The declared norm input is a certified upper bound, but it is placed in the denominator of the relative residual. H=[1], unit state and valid upper bound10^12 give reported residual10^-12 although true relative residual is1 and the kernel is trivial. This is a contract-level implication failure, not a new native execution result.',[ev(487,25,28),ev(487,48,58)],['054'],'Use an exact norm or a certified positive lower bound for a conservative upper bound on the relative residual; separately handle H=0 and pin which normalization the acceptance threshold measures.'),
('045','Positive-only sign interval leaves the explicitly forbidden R=I admissible','The Zolotarev prose correctly says GW residual alone cannot establish sign(H), but its minimax test covers only a positive interval where sign(x)=1. R=I satisfies this test and GW exactly while giving error2 on a negative eigenvalue. No oddness condition appears in the declaration.',[ev(478,43,49),ev(478,58,69)],['055'],'Require an odd rational form with verified reconstruction or certify both signed spectral intervals; bind coefficients, projected spectrum and residual error propagation.'),
('046','Topological susceptibility alternates between variance and second moment','The declaration uses (E[Q²]-E[Q]²)/V, whereas purpose, formal statement and reconstruction use E[Q²]/V without mean-zero premise. Constant charge1 makes the first0 and the second1 at unit volume.',[ev(476,28,31),ev(476,48,52),ev(476,82,86)],['056'],'Choose one definition, state any mean-zero assumption, and preserve mean charge with the evidence rather than silently dropping it.'),
('047','Witnessed irreflexivity does not define an indistinguishability quotient','WDNF promises quotient reconstruction but only requires support, witnessed distinct pairs and irreflexivity. Even a symmetric irreflexive difference containing only0≠2 has complement0~1 and1~2 but not0~2. An equivalence quotient is therefore not supplied by the declared conditions.',[ev(499,40,43),ev(499,79,93)],['057'],'Declare and verify the equivalence relation, or add apartness/cotransitivity conditions with a theorem proving the complement equivalence before quotient claims.'),
('048','Backward timelike pairs are labelled spacelike by lightcone criterion','The forward impossibility condition delta_t_max<distance/c is true for past-timelike as well as spacelike events. Same-position events at t=0 and t=-2 are classified by the rule named ruled_out_spacelike despite positive timelike squared interval. It correctly rejects forward propagation but not the stated geometric class.',[ev(490,65,70)],['058'],'Separate past-directed, spacelike and unresolved classifications; distinguish causal accessibility from actual cause/message receipt.'),
('049','Page-Wootters certification criteria omit their own global constraint premise','The nonclaims correctly require H_global Psi=0 and explicit interactions before deriving conditional time, but neither the declaration list nor validation/evidence binds H_global. The listed tests establish normalized slice agreement with a supplied unitary, not emergence from the stated independent constraint.',[ev(483,39,58),ev(483,119,128)],[],'Add the actual joint constraint and interaction decomposition with independent checking, or rename the outcome to finite conditional-history consistency.'),
('050','GTMUR certification flags contradict mandatory verifier/loss criteria','The GTMUR validation requires target-verifier acceptance and a loss ledger for lossy transport, while certification marks verifier_required=false and loss_ledger_required=false. A metadata-driven orchestrator can follow the weaker fields without satisfying the stated contract; the reviewed actual adapter has separate weak-certificate controls.',[ev(498,30,32),ev(498,40,65)],[],'Make certification flags conditional/required consistently and validate catalog invariants against the execution path; keep prior adapter failure evidence separate.'),
]
items={x['id']:x for x in r['findings']}
for k,title,detail,refs,probes,action in rows:items['PFPINFRA-F'+k]={'id':'PFPINFRA-F'+k,'severity':'medium','title':title,'finding':detail,'evidence':refs,'probes':['PFPINFRA-P'+x for x in probes],'next_action':action,'status':'open','scope':'Current declaration-level mathematical or binding defect; independent exact countermodel where named, no new production/native execution.'}
r['findings']=list(items.values());c={x['id']:x for x in r['claims']}
c['PFPINFRA-C017']={'id':'PFPINFRA-C017','claim':'Several newer contracts correctly distinguish feasibility from optimality, empirical scaling from complexity, detailed balance from mixing, semantic preservation from hashes, and mathematical verification from execution authority. These improve claim hygiene without themselves implementing the stated predicates.','evidence':[ev(496,39,79),ev(482,40,47),ev(477,40,51),ev(493,35,44),ev(497,42,50)],'dependencies':['A concrete admitted carrier and implementation binding','Independent witness validation and complete resource/budget accounting'],'limitations':['Other fields and older editions retain precise contradictions identified separately. No fresh native/model/empirical run is claimed.']}
r['claims']=list(c.values());vp=P+'_checks10.json';b=(H/vp).read_bytes();j=json.loads(b);v={x['path']:x for x in r['validation']};v[vp]={'path':vp,'sha256':hashlib.sha256(b).hexdigest(),'controls':len(j['outcomes']),'reproduced':len(j['outcomes']),'not_run':0,'python':j['python'],'scope':j['method']};r['validation']=list(v.values());rp.write_text(json.dumps(r,indent=2)+'\n')
